def glossary():
    body = '<p class="dek">Definitions for reading algae cultivation and single-cell research, with the measurement limitations that short dictionary entries often omit. Each term links to a deeper explanation.</p>\n<nav aria-label="Glossary terms"><p>'
    body += ' · '.join('<a href="#' + slug + '">' + html.escape(name) + '</a>' for slug, name, *_ in TERMS) + '</p></nav>'
    for slug, name, text, link, anchor in TERMS:
        body += '<section id="' + slug + '"><h2>' + html.escape(name) + '</h2><p>' + html.escape(text) + '</p><p><a href="' + link + '">' + html.escape(anchor) + '</a></p></section>\n'
    return body + '<h2>Sources and scope</h2><p>[1] <a href="' + PHENO + '">Behrendt et al. (2020), PhenoChip</a>. [2] <a href="' + BIOMASS + '">Schagerl et al. (2022), biomass and vitality measurement methods</a>. These sources explain measurement practice, not validated performance of Orr Biologicals hardware.</p><p>Use the <a href="/research/">research topic and methodology hub</a> to choose a reading path. This glossary is educational, not a cultivation protocol or food-safety assessment.</p>'


